const { useState } = React;

function App() {
  const [firstName, setFirstName] = useState("");
  const [lastName, setLastName] = useState("");
  const [topic, setTopic] = useState("");
  const [priority, setPriority] = useState("");
  const [issue, setIssue] = useState("");
  const [emailCopy, setEmailCopy] = useState(false);
  const [errors, setErrors] = useState({});

  function validate() {
    const newErrors = {};
    if (!firstName.trim()) newErrors.firstName = "First name is required.";
    if (!lastName.trim()) newErrors.lastName = "Last name is required.";
    if (!topic) newErrors.topic = "Topic is required.";
    if (!priority) newErrors.priority = "Priority is required.";
    if (!issue.trim()) newErrors.issue = "Please describe the issue.";
    return newErrors;
  }

  function handleSubmit(e) {
    e.preventDefault();
    const validationErrors = validate();
    setErrors(validationErrors);
    if (Object.keys(validationErrors).length === 0) {
      alert("Ticket submitted successfully!");
      // Reset form
      setFirstName("");
      setLastName("");
      setTopic("");
      setPriority("");
      setIssue("");
      setEmailCopy(false);
      setErrors({});
    }
  }

  return (
    <main style={styles.main}>
      <h2 style={styles.heading}>Support request</h2>
      <form onSubmit={handleSubmit} noValidate>
        <div style={styles.row}>
          <div style={styles.inputGroup}>
            <label htmlFor="firstName" style={styles.label}>First name</label>
            <input
              id="firstName"
              type="text"
              value={firstName}
              onChange={e => setFirstName(e.target.value)}
              style={styles.input}
              aria-describedby={errors.firstName ? "firstName-error" : undefined}
            />
            {errors.firstName && (
              <p id="firstName-error" role="alert" style={styles.error}>
                {errors.firstName}
              </p>
            )}
          </div>
          <div style={styles.inputGroup}>
            <label htmlFor="lastName" style={styles.label}>Last name</label>
            <input
              id="lastName"
              type="text"
              value={lastName}
              onChange={e => setLastName(e.target.value)}
              style={styles.input}
              aria-describedby={errors.lastName ? "lastName-error" : undefined}
            />
            {errors.lastName && (
              <p id="lastName-error" role="alert" style={styles.error}>
                {errors.lastName}
              </p>
            )}
          </div>
        </div>

        <div style={styles.inputGroup}>
          <label htmlFor="topic" style={styles.label}>Topic</label>
          <select
            id="topic"
            value={topic}
            onChange={e => setTopic(e.target.value)}
            style={styles.select}
            aria-describedby={errors.topic ? "topic-error" : undefined}
          >
            <option value="">Select a topic</option>
            <option value="Billing">Billing</option>
            <option value="Technical">Technical</option>
            <option value="Other">Other</option>
          </select>
          {errors.topic && (
            <p id="topic-error" role="alert" style={styles.error}>
              {errors.topic}
            </p>
          )}
        </div>

        <fieldset style={styles.fieldset}>
          <legend style={styles.legend}>Priority</legend>
          <div style={styles.radioGroup}>
            <label style={styles.radioLabel}>
              <input
                type="radio"
                name="priority"
                value="Low"
                checked={priority === "Low"}
                onChange={e => setPriority(e.target.value)}
              /> Low
            </label>
            <label style={styles.radioLabel}>
              <input
                type="radio"
                name="priority"
                value="Medium"
                checked={priority === "Medium"}
                onChange={e => setPriority(e.target.value)}
              /> Medium
            </label>
            <label style={styles.radioLabel}>
              <input
                type="radio"
                name="priority"
                value="High"
                checked={priority === "High"}
                onChange={e => setPriority(e.target.value)}
              /> High
            </label>
          </div>
          {errors.priority && (
            <p role="alert" style={styles.error}>
              {errors.priority}
            </p>
          )}
        </fieldset>

        <div style={styles.inputGroup}>
          <label htmlFor="issue" style={styles.label}>Describe the issue</label>
          <textarea
            id="issue"
            value={issue}
            onChange={e => setIssue(e.target.value)}
            rows={5}
            style={styles.textarea}
            aria-describedby={errors.issue ? "issue-error" : undefined}
          />
          {errors.issue && (
            <p id="issue-error" role="alert" style={styles.error}>
              {errors.issue}
            </p>
          )}
        </div>

        <div style={styles.checkboxGroup}>
          <label>
            <input
              type="checkbox"
              checked={emailCopy}
              onChange={e => setEmailCopy(e.target.checked)}
            /> Email me a copy
          </label>
        </div>

        <button type="submit" style={styles.button}>Submit ticket</button>
      </form>
    </main>
  );
}

